            if inp[i][j]!=bg and (i,j) not in seen:
                st=[(i,j)]; comp=[]; v=inp[i][j]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen: continue
                    seen.add((a,b)); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and inp[x][y]==v: st.append((x,y))
                comps.append(comp)
    out=[[bg]*W for _ in range(H)]
    for comp in comps:
        rmax=max(p[0] for p in comp)
        for c in range(W):
            if any(p==(rmax,c) for p in comp): out[rmax][c]=inp[rmax][c]
        for (rr,cc) in comp:
            if rr==rmax: continue
            ncc=cc+1
            if ncc<W and out[rr][ncc] in (bg, inp[rr][cc]):
                out[rr][ncc]=inp[rr][cc]
    return out
