        bot=max(ys)
        rows=set(p[0] for p in comp)
        for y in rows-{bot}:
            # simultaneous shift right for the WHOLE row among comp cells
            new=g[y][:]
            for x in range(W):
                # incoming from x-1 only if that cell is non-bg
                if x>=1 and g[y][x-1]!=bg:
                    new[x]=g[y][x-1]
                else:
                    new[x]=bg
            g[y]=new[:]
    return g

