def comps_of(g,bg):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for y in range(H):
        for x in range(W):
            if g[y][x]!=bg and (y,x) not in seen:
                st=[(y,x)]; c=set()
                while st:
                    cy,cx=st.pop()
                    if (cy,cx) in c: continue
                    c.add((cy,cx)); seen.add((cy,cx))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]!=bg and (ny,nx) not in c: st.append((ny,nx))
                out.append(c)
    return out

