def sim(grid, variant='parallel_rigid', verbose=False):
    H,W=len(grid),len(grid[0]); bg=C(v for r in grid for v in r).most_common(1)[0][0]
    def f(g_,v):
        H,W=len(g_),len(g_[0]); bg_=C(v for r in g_ for v in r).most_common(1)[0][0]
        cs=comps_of(g_,bg_)
        # try serial rigid comp shift, right-to-left? order options
        out=[r[:] for r in g_]
        if v=='parallel_rigid':
            mv=True
            while mv:
                mv=False; new=[r[:] for r in out]
                for c_ in sorted(cs,key=lambda c_:min(p[0] for p in c_)):
                    ys={p[0] for p in c_}
                    tgt=[(y,x+1) for y,x in c_]
                    ok=all(0<=yy<H and 0<=xx<W and (new[yy][xx]==bg_ or (yy,xx) in c_) for yy,xx in tgt)
                    if ok:
                        for (y,x) in c_:
                            ny,nx=tgt[c_.index((y,x))]
                            if ny,nx!=(y,x): new[ny][nx]=g_[y][x]
                        mv=True
                if mv: out=new
        elif v=='serial_rigid_readorder':
            out=[r[:] for r in g_]; changed=True
            while changed:
                changed=False
                for c_ in sorted(cs,key=lambda c_: (min(p[0] for p in c_),min(p[1] for p in c_))):
                    ys={p[0] for p in c_}; xs={p[1] for p in c_}
                    tgt=[(y,x+1) for y,x in c_]
                    ok=all(0<=yy<H and 0<=xx<W and (out[yy][xx]==bg_ or (yy,xx) in c_) for yy,xx in tgt)
                    if ok:
                        newo=[r[:] for r in out]
                        for idx,(y,x) in enumerate(c_):
                            newo[tgt[idx][0]][tgt[idx][1]]=g_[y][x]
                        out=newo; changed=True; break
        elif v=='percell':
            out=[r[:] for r in g_]; mv=True
            while mv:
                mv=False; newo=[r[:] for r in out]
                for c_ in cs:
                    for (y,x) in c_:
                        if out[y][x]!=bg_:
                            nx=x+1
                            if 0<=nx<W and out[y][nx]==bg_:
                                newo[y][nx]=out[y][x]; mv=True
                out=newo
        elif v=='percell_adjblock':
            out=[r[:] for r in g_]; mv=True
            while mv:
                mv=False; newo=[r[:] for r in out]
                for c_ in cs:
                    for (y,x) in c_:
                        if out[y][x]!=bg_:
                            nx=x+1
                            if 0<=nx<W and out[y][nx]==bg_:
                                # adjacency check: does moving create contact with any non-bg cell?
                                tgt=(y,nx)
                                bad=any(0<=ty+dy<H and 0<=tx+dx<W and out[ty+dy][tx+dx]!=bg_
                                      for ty,tx in (tgt) for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)))
                                if not bad:
                                    newo[y][nx]=out[y][x]; mv=True
                out=newo
        return out
    oexp=f(grid,v)
    exp=G[nm+' output']
    return oexp==exp

